cd /tmp/vally-eval-trial-hfBcFf && cat > src/CheckoutPricing.Application/Checkout.cs <<'E'
namespace CheckoutPricing.Application;

public enum CustomerTier { Standard, Gold }

public sealed class Checkout
{
    public decimal CalculatePayableTotal(CustomerTier tier, decimal orderSubtotal) => orderSubtotal;
}
E
mkdir -p tests/CheckoutPricing.IntegrationTests/Pricing && cat > tests/CheckoutPricing.IntegrationTests/Pricing/LoyaltyDiscountTests.cs <<'E'
using CheckoutPricing.Application;

namespace CheckoutPricing.IntegrationTests.Pricing;

public sealed class LoyaltyDiscountTests
{
    [Fact]
    public void Gold_customer_receives_the_approved_discount()
    {
        var checkout = new Checkout();

        var payable = checkout.CalculatePayableTotal(CustomerTier.Gold, 100.00m);

        Assert.Equal(95.00m, payable);
    }
}
E
dotnet test tests/CheckoutPricing.IntegrationTests 2>&1 | grep -vi "^\s*$" | tail -20

